// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 callCount) public {
        uint256 n = bound(callCount, 1, 10);
        for (uint256 i = 0; i < n; i++) {
            address player = address(uint160(i + 1));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
        }
        uint256 expectedPot = n * 10;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("pot()"));
        assertTrue(ok && c.pot() == expectedPot);
    }
}
